CREATE TABLE products (id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL,price NUMERIC(10,2) NOT NULL CHECK(price>=0),stock INT NOT NULL DEFAULT 0 CHECK(stock>=0));
CREATE TABLE customers (id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,city VARCHAR(80) NOT NULL);
CREATE TABLE orders (id SERIAL PRIMARY KEY,customer_id INT NOT NULL REFERENCES customers(id),total NUMERIC(12,2) NOT NULL CHECK(total>=0),status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE order_items (id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id),product_id INT NOT NULL REFERENCES products(id),quantity INT NOT NULL CHECK(quantity>0),unit_price NUMERIC(10,2) NOT NULL);
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'chatbot_reader') THEN CREATE ROLE chatbot_reader LOGIN PASSWORD 'readerpass'; END IF; END $$;
